function cleanTitle(str) {
    if (!str) return '';
    return str.replace(/\(From "[^"]*"\)/gi, '').replace(/\(feat\.[^)]*\)/gi, '').replace(/-\s*New Version/gi, '').replace(/-\s*Original/gi, '').replace(/\s*\(From\s+.*?\)/gi, '').replace(/•.*/gi, '').trim();
}
function parseLrc(lrcText) {
    if (!lrcText) return [];
    const lines = lrcText.split('\n');
    const result = [];
    const timeRegex = /\[(\d{2}):(\d{2})(?:\.(\d{2,3}))?\]/g;
    for (const line of lines){
        const trimmed = line.trim();
        if (!trimmed) continue;
        let match;
        timeRegex.lastIndex = 0;
        // A line might have multiple timestamps, e.g. [00:12.30][00:45.10] Chorus
        const timestamps = [];
        while((match = timeRegex.exec(trimmed)) !== null){
            const minutes = parseInt(match[1], 10);
            const seconds = parseInt(match[2], 10);
            const millis = match[3] ? parseInt(match[3].padEnd(3, '0').slice(0, 3), 10) : 0;
            const totalSeconds = minutes * 60 + seconds + millis / 1000;
            timestamps.push(totalSeconds);
        }
        const cleanText = trimmed.replace(/\[\d{2}:\d{2}(?:\.\d{2,3})?\]/g, '').trim();
        if (cleanText) {
            timestamps.forEach((time)=>{
                result.push({
                    time,
                    text: cleanText
                });
            });
        }
    }
    // Sort chronologically
    return result.sort((a, b)=>a.time - b.time);
}
